#!/usr/bin/env bash
# hooks/pre-commit/size-guard.sh
#
# Enforces ADR-0003's size guard: rejects any single staged file larger than
# SIZE_LIMIT_BYTES unless the file matches an allow-list entry.
#
# Purpose: prevent accidental commits of GGUFs, safetensors, wheels, tarballs,
# or other large artifacts that belong under `models/`, `vendor/`, or `.venv/`
# and should be regenerated by scripts, not tracked.
#
# Exit codes:
#   0 — all staged files within limit (or allow-listed)
#   1 — one or more oversized files detected

set -euo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel)"
cd "$REPO_ROOT"

# 10 MiB
SIZE_LIMIT_BYTES=$((10 * 1024 * 1024))

# Files exempt from the size check. Empty by default; add entries here with
# explicit justification if a large tracked artifact is ever needed.
ALLOW_LIST_RE='^$'   # matches nothing

# Staged files only (skip when nothing is staged so `bash size-guard.sh` from
# a clean tree is a no-op).
if ! git diff --cached --name-only --diff-filter=ACMRT | grep -q .; then
  exit 0
fi

VIOLATIONS=""
while IFS= read -r f; do
  [ -z "$f" ] && continue
  [ ! -f "$f" ] && continue
  if [[ "$f" =~ $ALLOW_LIST_RE ]]; then
    continue
  fi
  size=$(stat -c '%s' "$f" 2>/dev/null || wc -c < "$f")
  if [ "$size" -gt "$SIZE_LIMIT_BYTES" ]; then
    human=$(numfmt --to=iec --suffix=B "$size" 2>/dev/null || echo "${size}B")
    VIOLATIONS+="${f} (${human}, limit $(numfmt --to=iec --suffix=B "$SIZE_LIMIT_BYTES"))"$'\n'
  fi
done < <(git diff --cached --name-only --diff-filter=ACMRT)

if [ -n "$VIOLATIONS" ]; then
  echo "========================================================================"
  echo "PRE-COMMIT FAILURE — file(s) exceed size guard (ADR-0003)"
  echo "Regenerable artifacts (models, venvs, build outputs) must not be tracked."
  echo "See ADR-0003 for the three-category rule."
  echo "------------------------------------------------------------------------"
  printf '%s' "$VIOLATIONS"
  echo "========================================================================"
  echo "If this file genuinely belongs in git, add it to ALLOW_LIST_RE in"
  echo "hooks/pre-commit/size-guard.sh with justification in the commit."
  echo "To bypass this check (NOT RECOMMENDED), re-run with: git commit --no-verify"
  exit 1
fi

exit 0
